#include <cctype>
#include <string>
#include <vector>

static std::string normal(std::string s)
{
    if (!s.empty() && s.back() == '.') s.pop_back();
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

static std::vector<std::string> labels(const std::string& s)
{
    std::vector<std::string> out;
    std::size_t start{ 0 };
    while (true)
    {
        const std::size_t dot{ s.find('.', start) };
        out.push_back(s.substr(start, dot == std::string::npos ? std::string::npos : dot - start));
        if (dot == std::string::npos) break;
        start = dot + 1;
    }
    return out;
}

static bool isIPv4(const std::string& host)
{
    const auto parts{ labels(host) };
    if (parts.size() != 4) return false;
    for (const std::string& p : parts)
    {
        if (p.empty() || p.size() > 3) return false;
        for (char c : p) if (!std::isdigit(static_cast<unsigned char>(c))) return false;
    }
    return true;
}

bool nameMatches(const std::string& certificateName, const std::string& host)
{
    const std::string name{ normal(certificateName) }, h{ normal(host) };
    if (name.empty() || h.empty()) return false;
    if (name.find('*') == std::string::npos) return name == h;
    const auto nameLabels{ labels(name) }, hostLabels{ labels(h) };
    if (nameLabels[0] != "*") return false;
    for (std::size_t i{ 1 }; i < nameLabels.size(); ++i) if (nameLabels[i].find('*') != std::string::npos) return false;
    if (nameLabels.size() < 3 || isIPv4(h)) return false;
    if (hostLabels.size() != nameLabels.size() || hostLabels[0].empty()) return false;
    for (std::size_t i{ 1 }; i < nameLabels.size(); ++i) if (nameLabels[i] != hostLabels[i]) return false;
    return true;
}

bool certificateMatches(const std::vector<std::string>& names, const std::string& host)
{
    for (const std::string& n : names) if (nameMatches(n, host)) return true;
    return false;
}

unitTests:
TEST("exact names") {
    CHECK(nameMatches("xenon.justloofy.dev", "xenon.justloofy.dev"));
    CHECK(nameMatches("Xenon.JustLoofy.dev", "xenon.justloofy.DEV."));
    CHECK(!nameMatches("xenon.justloofy.dev", "justloofy.dev"));
    CHECK(!nameMatches("", "x"));
}
TEST("wildcards cover exactly one label") {
    CHECK(nameMatches("*.justloofy.dev", "xenon.justloofy.dev"));
    CHECK(nameMatches("*.justloofy.dev", "WORKOUTS.justloofy.dev"));
    CHECK(!nameMatches("*.justloofy.dev", "justloofy.dev"));
    CHECK(!nameMatches("*.justloofy.dev", "a.b.justloofy.dev"));
    CHECK(!nameMatches("*.justloofy.dev", ".justloofy.dev"));
}
TEST("bad wildcards never match") {
    CHECK(!nameMatches("*.dev", "justloofy.dev"));
    CHECK(!nameMatches("*", "localhost"));
    CHECK(!nameMatches("x*.example.com", "xy.example.com"));
    CHECK(!nameMatches("a.*.example.com", "a.b.example.com"));
    CHECK(!nameMatches("*.*.example.com", "a.b.example.com"));
    CHECK(!nameMatches("*.0.0.1", "127.0.0.1"));
}
TEST("a certificate with several names") {
    const std::vector<std::string> names{ "justloofy.dev", "*.justloofy.dev" };
    CHECK(certificateMatches(names, "justloofy.dev"));
    CHECK(certificateMatches(names, "xenon.justloofy.dev"));
    CHECK(!certificateMatches(names, "evil.dev"));
    CHECK(!certificateMatches({}, "justloofy.dev"));
}

